<nav class="flex flex-wrap gap-3" aria-label="Fiscal years"><a class="btn btn-ghost" href="<?= pl_e(pl_url('/year-end')) ?>">New fiscal year</a><?php foreach($years as $row): ?><a class="btn btn-ghost" href="<?= pl_e(pl_url('/year-end',['id'=>$row['id']])) ?>"><?= pl_e($row['end_date'].' · '.$row['status']) ?></a><?php endforeach; ?></nav>
<?php if($year): ?><h2 class="section-title"><?= pl_e($year['start_date'].' — '.$year['end_date'].' · '.$year['status']) ?></h2><p>Policy: <?= pl_e($year['policy']['legal_basis'].' · '.$year['policy']['treatment']) ?>. <?= pl_e($year['policy']['review_note']) ?></p><?php endif; ?>
