<label>Accounting treatment<select class="input" name="treatment" required><option value="">Choose explicitly</option><?php foreach(['company'=>'Company: retained earnings','sole_trader'=>'Sole trader: owner capital','partnership'=>'Partnership: agreed appropriation'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($selectedPolicy['treatment']??'')===$key?'selected':'' ?>><?= pl_e($label) ?></option><?php endforeach; ?></select></label>
<label>Legal form and agreement basis<input class="input" name="legal_basis" required maxlength="500" value="<?= pl_e($selectedPolicy['legal_basis']??'') ?>"></label>
<label>Company retained earnings / sole-trader capital<select class="input" name="destination_account_id"><?php $accountOptions($accounts,(int)($selectedPolicy['destination_account_id']??0),false); ?></select></label>
