<fieldset class="border border-border p-3"><legend>Partner <?= $i+1 ?></legend><label>Partner<select class="input" name="partner_id[]"><option value="">Unused</option><?php foreach($partners as $partner): ?><option value="<?= (int)$partner['id'] ?>" <?= (int)($input['partner_id'][$i]??$p['partner_id']??0)===(int)$partner['id']?'selected':'' ?>><?= pl_e($partner['name']) ?></option><?php endforeach; ?></select></label><label>Reviewed ratio<input class="input" name="ratio[]" inputmode="decimal" placeholder="0.600000" value="<?= pl_e($input['ratio'][$i]??$p['ratio']??'') ?>"></label><label>Fixed-capital current account<select class="input" name="current_account_id[]"><?php $accountOptions($accounts,(int)($input['current_account_id'][$i]??$p['destination_account_id']??0),false); ?></select></label></fieldset>
<?php endfor; ?>
<label>Policy review note<textarea class="input" name="note" required maxlength="1000"><?= pl_e($input['note']??$selectedPolicy['review_note']??'') ?></textarea></label><button class="btn btn-primary" type="submit"><?= $year?'Save revised policy':'Create reviewed fiscal year' ?></button></form></details>
<?php endif; ?>
<?php if($previewError!==''): ?><p class="alert alert-warning"><?= pl_e($previewError) ?></p><?php endif; ?>
<?php if($preview): ?><div class="rounded-panel border border-border p-4"><h2 class="section-title">Closing preview</h2><p>Unclosed result: <?= pl_e(pl_money($preview['profit'])) ?></p><?php foreach($preview['blockers'] as $blocker): ?><p class="alert alert-warning"><?= pl_e($blocker) ?></p><?php endforeach; ?>
