<?php foreach($preview['allocations'] as $allocation): ?><p><?= pl_e(($allocation['name']??'Earnings destination').': result '.$allocation['amount'].', drawings '.$allocation['drawings'].', net credit '.$allocation['net_credit']) ?></p><?php endforeach; ?></div><?php endif; ?>
<?php if($canManage&&$year): ?>
<?php if($year['status']==='closing'): ?><details class="rounded-panel border border-border p-4"><summary class="section-title">Post final-day adjustment</summary><p>Dated <?= pl_e($year['end_date']) ?>. Both sides must balance. Correct errors using the linked reversal action, then post a replacement.</p><form method="post" action="<?= pl_e(pl_url('/year-end')) ?>" class="grid gap-3"><?php $fields('adjust'); ?><label>Adjustment reason<input class="input" name="note" required maxlength="400"></label><?php for($i=0;$i<4;$i++): ?><fieldset class="grid grid-cols-1 sm:grid-cols-3 gap-2"><legend>Line <?= $i+1 ?></legend><label>Account<select class="input" name="account_id[]"><?php $accountOptions($accounts); ?></select></label><label>Debit<input class="input" name="debit[]" value="0" inputmode="decimal"></label><label>Credit<input class="input" name="credit[]" value="0" inputmode="decimal"></label></fieldset><?php endfor; ?><button class="btn btn-primary">Post reviewed adjustment</button></form></details><?php endif; ?>
<?php $actions=match($year['status']){'open'=>['start'=>'Start closing'],'closing'=>['close'=>'Close reviewed fiscal year','prepare'=>'Return to preparation'],'closed'=>['lock'=>'Lock fiscal year','reopen'=>'Reopen for correction'],'locked'=>['reopen'=>'Reopen for correction'],default=>[]};foreach($actions as $action=>$label): ?>
<form method="post" action="<?= pl_e(pl_url('/year-end')) ?>" class="rounded-panel border border-border p-4 grid gap-3"><?php $fields($action); ?><h2 class="section-title"><?= pl_e($label) ?></h2><?php if($action==='close'): ?><input type="hidden" name="fingerprint" value="<?= pl_e($preview['fingerprint']??'') ?>"><?php foreach(['stock'=>'Stock counts and valuation agreed','provisions'=>'Provisions reviewed','adjustments'=>'Adjusting journals complete','payroll'=>'Payroll reviewed'] as $key=>$text): ?><label><input type="checkbox" name="<?= $key ?>" value="1" required> <?= pl_e($text) ?> (or not applicable, explained below)</label><?php endforeach; ?><?php endif; ?><label>Review / correction note<textarea class="input" name="note" required maxlength="1000"></textarea></label><button class="btn btn-primary" <?= $action==='close'&&(!$preview||!$preview['ready'])?'disabled':'' ?>><?= pl_e($label) ?></button></form>
<?php endforeach;endif; ?>
<?php if($canManage&&$year&&$year['status']==='closing'): ?><details class="rounded-panel border border-border p-4"><summary class="section-title">Reverse a year-end adjustment</summary><form method="post" action="<?= pl_e(pl_url('/year-end')) ?>" class="grid gap-3"><?php $fields('reverse_adjustment'); ?><label>Original adjustment journal ID<input class="input" name="journal_id" type="number" min="1" required></label><label>Correction reason<input class="input" name="note" required maxlength="400"></label><button class="btn btn-primary">Post linked adjustment reversal</button></form></details><?php endif; ?>
<?php if($report): ?><h2 class="section-title">Reports and comparatives</h2><p>Use your browser's Print command for these trial balances and comparative totals. Closing entries are excluded from performance reports. These reports reflect all postings currently recorded.</p>
<div class="overflow-x-auto"><table class="table"><thead><tr><th>Report</th><th>This year</th><th>Previous registered year</th></tr></thead><tbody><tr><td>Net profit</td><td><?= pl_e($report['profit_loss']['net_profit']) ?></td><td><?= pl_e($report['comparative']['profit_loss']['net_profit']??'Not available') ?></td></tr><tr><td>Assets</td><td><?= pl_e($report['balance_sheet']['total_assets']) ?></td><td><?= pl_e($report['comparative']['balance_sheet']['total_assets']??'Not available') ?></td></tr></tbody></table></div>
<?php foreach(['unadjusted_trial_balance'=>'Pre-adjustment trial balance','adjusted_trial_balance'=>'Post-adjustment trial balance'] as $key=>$title): ?><details open><summary class="section-title"><?= pl_e($title) ?></summary><div class="overflow-x-auto"><table class="table"><thead><tr><th>Account</th><th>Debit</th><th>Credit</th></tr></thead><tbody><?php $debit='0.0000';$credit='0.0000';foreach($report[$key] as $a): if(bccomp($a['balance'],'0',4)===0){continue;}$d=bccomp($a['balance'],'0',4)>0?$a['balance']:'0.0000';$c=bccomp($a['balance'],'0',4)<0?bcsub('0',$a['balance'],4):'0.0000';$debit=bcadd($debit,$d,4);$credit=bcadd($credit,$c,4); ?><tr><td><?= pl_e($a['code'].' · '.$a['name']) ?></td><td><?= pl_e($d) ?></td><td><?= pl_e($c) ?></td></tr><?php endforeach; ?><tr><th>Total</th><th><?= pl_e($debit) ?></th><th><?= pl_e($credit) ?></th></tr></tbody></table></div></details><?php endforeach; ?>
<h2 class="section-title">Audit history</h2><?php foreach($report['history'] as $entry): ?><p><?= pl_e($entry['created_at'].' · '.$entry['display_name'].' · '.$entry['action'].' · '.$entry['review_note']) ?> <?php if($entry['journal_id']): ?><a href="<?= pl_e(pl_url('/journals/detail',['id'=>$entry['journal_id']])) ?>">Journal <?= (int)$entry['journal_id'] ?></a><?php endif; ?></p><?php if($entry['policy']): ?><details><summary>Policy recorded for this action</summary><p><?= pl_e($entry['policy']['legal_basis'].' � '.$entry['policy']['treatment'].' � '.$entry['policy']['review_note']) ?></p><?php foreach($entry['policy']['partners']??[] as $partner): ?><p><?= pl_e($partner['name'].' � ratio '.$partner['ratio'].' � destination account '.$partner['destination_account_id']) ?></p><?php endforeach; ?><?php foreach($entry['allocations'] as $allocation): ?><p><?= pl_e(($allocation['name']??'Earnings destination').': allocated '.$allocation['amount'].', drawings '.$allocation['drawings'].', net credit '.$allocation['net_credit']) ?></p><?php endforeach; ?></details><?php endif; ?><?php endforeach;endif; ?>
</section>
